class HapticSystem{constructor(){this.supported='vibrate' in navigator;this.enabled=localStorage.getItem('hapticsEnabled')!=='false';}patterns={light:[10],medium:[30],heavy:[50],success:[30,10,30],error:[100,50,100],notification:[50,30,50,30,50],heartbeat:[50,100,50],burst:[20,20,20,20,20]};trigger(pattern='light'){if(!this.supported || !this.enabled)return;const vibrationPattern=this.patterns[pattern] || this.patterns.light;try{navigator.vibrate(vibrationPattern);}catch(error){console.warn('Haptic feedback failed:',error);}}toggle(){this.enabled=!this.enabled;localStorage.setItem('hapticsEnabled',this.enabled);if(this.enabled){this.trigger('success');}return this.enabled;}isEnabled(){return this.supported && this.enabled;}isSupported(){return this.supported;}}window.hapticSystem=new HapticSystem();console.log(`📳 Haptic system loaded(${window.hapticSystem.isSupported()? 'supported':'not supported'})`);